"724 :   String getReadableJSTypeName(Node n, boolean dereference) {
725 : 
726 :     // The best type name is the actual type name.
727 : 
728 :     // If we're analyzing a GETPROP, the property may be inherited by the
729 :     // prototype chain. So climb the prototype chain and find out where
730 :     // the property was originally defined.
731 :     if (n.isGetProp()) {
732 :       ObjectType objectType = getJSType(n.getFirstChild()).dereference();
733 :       if (objectType != null) {
734 :         String propName = n.getLastChild().getString();
735 :         if (objectType.getConstructor() != null &&
736 :             objectType.getConstructor().isInterface()) {
737 :           objectType = FunctionType.getTopDefiningInterface(
738 :               objectType, propName);
739 :         } else {
740 :           // classes
741 :           while (objectType != null && !objectType.hasOwnProperty(propName)) {
742 :             objectType = objectType.getImplicitPrototype();
743 :           }
744 :         }
745 : 
746 :         // Don't show complex function names or anonymous types.
747 :         // Instead, try to get a human-readable type name.
748 :         if (objectType != null &&
749 :             (objectType.getConstructor() != null ||
750 :              objectType.isFunctionPrototypeType())) {
751 :           return objectType.toString() + "." + propName;
752 :         }
753 :       }
754 :     }
755 : 
756 :     JSType type = getJSType(n);
757 :     if (dereference) {
758 :       ObjectType dereferenced = type.dereference();
759 :       if (dereferenced != null) {
760 :         type = dereferenced;
761 :       }
762 :     }
763 :     if (type.isFunctionPrototypeType() ||
764 :         (type.toObjectType() != null &&
765 :          type.toObjectType().getConstructor() != null)) {
766 :       return type.toString();
767 :     }
768 :     String qualifiedName = n.getQualifiedName();
769 :     if (qualifiedName != null) {
770 :       return qualifiedName;
771 :     } else if (type.isFunctionType()) {
772 :       // Don't show complex function names.
773 :       return "function";
774 :     } else {
775 :       return type.toString();
776 :     }
777 :   }"

